# COPY — generated by build_repo_mirror.R. Do not edit here. Working copy: data_workspace_2026-07/ch3_pipeline_restored/scripts/41m_staffing_calibrate_butler.R
# 41m_staffing_calibrate_butler.R
#
# Replace the flat, never-validated pre-2010 MP staffing placeholder
# (data/raw/staffing_pre2010_modelled.csv: HC allowance maxima x an assumed
# constant 85% utilisation rate) with a calibrated series built from real
# printed maxima — Butler & Butler (2011), British Political Facts, p.363,
# photographed by PJ in London 7 Sep 2026 (see
# sources_raw/butler_butler_2011_mp_allowances/SOURCE_NOTE.md).
#
# PJ, 7 Sep: "we may have to do a bit of backward induction to get an
# estimate but better than what we have" — same method as the trust-series
# extension (41k/41l): find real overlap years, derive an EMPIRICAL
# calibration ratio there (not an assumed one), apply it back across the
# gap, report multiple specs rather than picking one silently.
#
# METHOD
# ------
# 1. Butler & Butler gives NOMINAL maxima ("the figure shown is the maximum
#    payable") for 1969-2019 (extended 7 Sep from the 12th-edition draft,
#    british_political_facts_12_v5/, which adds real 2017-19 rows beyond the
#    2011/2018 editions). 1991 was initially miscoded as a gap (cropped out
#    of both photos) and a transcription error at 2001 went unnoticed until
#    a cross-check against the Mortimore & Blick (2018) successor edition's
#    identical table caught both — see SOURCE_NOTE.md, 7 Sep.
# 2. IPSA (data/processed/ipsa_staffing_annual.csv) gives real, published
#    ACTUAL nominal + real-2015 spend for 2012-2024. Both sources cover
#    2012-2019 (widened 7 Sep from 2012-2016) -> that overlap gives an
#    EMPIRICAL maximum-to-actual utilisation ratio, year by year, replacing
#    the placeholder's assumed flat 85%.
# 3. The ratio is computed in NOMINAL terms (same-year numerator and
#    denominator), so it is deflator-independent by construction.
# 4. A deflator (real-2015 / nominal) is still needed to express the
#    calibrated 1979-2010 estimate in real terms. Rather than sourcing a
#    fresh RPI series and risking inconsistency with whatever the project
#    already used, the deflator is BACKED OUT of the existing
#    staffing_pre2010_modelled.csv and ipsa_staffing_annual.csv files
#    themselves (both already carry paired nominal/real_2015 columns at
#    their anchor years) and log-linearly interpolated across 1979-2016.
#    This guarantees consistency with the existing pipeline without
#    re-deriving RPI independently.
#
# OUTPUTS:
#   data/processed/staffing_pre2010_calibrated_butler.csv  (replacement series)
#   data/processed/staffing_calibration_robustness.csv     (ratio specs)
# Old placeholder is left untouched at data/raw/staffing_pre2010_modelled.csv
# for comparison — NOT deleted, NOT overwritten.

suppressMessages({library(dplyr); library(readr); library(tibble)})

.ROOT <- local({
  a <- commandArgs(trailingOnly = FALSE)
  m <- grep("^--file=", a, value = TRUE)
  if (length(m) == 1) normalizePath(file.path(dirname(sub("^--file=", "", m)), ".."))
  else getwd()
})
PROJECT   <- .ROOT
WKBD_ROOT <- normalizePath(file.path(PROJECT, "..", ".."))

BUTLER_IN   <- file.path(WKBD_ROOT, "sources_raw/butler_butler_2011_mp_allowances/mp_office_expenses_allowance_max_1969_2016.csv")
PLACEHOLDER <- file.path(PROJECT, "data/raw/staffing_pre2010_modelled.csv")
IPSA_IN     <- file.path(PROJECT, "data/processed/ipsa_staffing_annual.csv")
OUT_CSV     <- file.path(PROJECT, "data/processed/staffing_pre2010_calibrated_butler.csv")
OUT_ROB     <- file.path(PROJECT, "data/processed/staffing_calibration_robustness.csv")

butler <- read_csv(BUTLER_IN, show_col_types = FALSE)
old    <- read_csv(PLACEHOLDER, show_col_types = FALSE)
ipsa   <- read_csv(IPSA_IN, show_col_types = FALSE)

# ============================================================
# 1. DEFLATOR — backed out of the project's own existing real_2015 columns,
#    log-linearly interpolated. NOT a freshly-sourced RPI series.
# ============================================================
deflator_anchors <- bind_rows(
  old  |> transmute(year = cal_year, ratio = mean_staffing_real_2015 / mean_staffing_nominal),
  ipsa |> transmute(year = cal_year, ratio = mean_staffing_real_2015 / mean_staffing_nominal)
) |> distinct(year, .keep_all = TRUE) |> arrange(year)

cat("Deflator anchors (real_2015 / nominal), backed out of existing data:\n")
print(deflator_anchors, n = Inf)

deflate <- function(year) {
  exp(approx(deflator_anchors$year, log(deflator_anchors$ratio), xout = year, rule = 2)$y)
}

# ============================================================
# 2. EMPIRICAL UTILISATION RATIO — Butler & Butler max vs IPSA actual,
#    2012-2019 overlap (widened 7 Sep from 2012-2016 using the 12th-edition
#    draft's 2017-19 rows), NOMINAL terms (deflator-independent).
# ============================================================
overlap <- ipsa |>
  filter(cal_year %in% 2012:2019) |>
  transmute(year = cal_year, ipsa_nominal_actual = mean_staffing_nominal) |>
  inner_join(butler |> transmute(year, butler_nominal_max = office_expenses_max_nominal),
             by = "year") |>
  mutate(utilisation_ratio = ipsa_nominal_actual / butler_nominal_max)

cat("\nEmpirical utilisation ratio, overlap years (IPSA actual / Butler&Butler maximum):\n")
print(overlap)

ratio_mean <- mean(overlap$utilisation_ratio)
ratio_min  <- min(overlap$utilisation_ratio)
ratio_max  <- max(overlap$utilisation_ratio)

cat(sprintf("\nRatio across %d overlap years: mean=%.3f, min=%.3f, max=%.3f (old placeholder assumed a flat 0.85)\n",
            nrow(overlap), ratio_mean, ratio_min, ratio_max))

robustness <- tibble(
  spec  = c("mean_ratio", "min_ratio", "max_ratio", "old_flat_85pct"),
  ratio = c(ratio_mean, ratio_min, ratio_max, 0.85)
)
write_csv(robustness, OUT_ROB)

# ============================================================
# 3. APPLY — 1979-2010, real Butler&Butler maxima x each ratio spec,
#    converted to real-2015 via the backed-out deflator. 1991 is a genuine
#    gap in the source (confirmed against the physical book) and is left
#    NA, not interpolated.
# ============================================================
pre2010 <- butler |>
  filter(year <= 2010) |>
  mutate(
    deflator_ratio = deflate(year),
    nominal_mean   = office_expenses_max_nominal * ratio_mean,
    nominal_min    = office_expenses_max_nominal * ratio_min,
    nominal_max    = office_expenses_max_nominal * ratio_max,
    nominal_old85  = office_expenses_max_nominal * 0.85,
    real_2015_mean = nominal_mean  * deflator_ratio,
    real_2015_min  = nominal_min   * deflator_ratio,
    real_2015_max  = nominal_max   * deflator_ratio,
    real_2015_old85 = nominal_old85 * deflator_ratio
  ) |>
  select(year, office_expenses_max_nominal, deflator_ratio,
         real_2015_mean, real_2015_min, real_2015_max, real_2015_old85, note)

write_csv(pre2010, OUT_CSV)

cat("\nCalibrated pre-2010 series (real terms, 2015 prices) — headline spec (mean ratio):\n")
print(pre2010 |> select(year, real_2015_mean, note), n = Inf)

cat("\nComparison at the old 8-anchor years, calibrated vs placeholder:\n")
comp <- pre2010 |>
  filter(year %in% old$cal_year) |>
  select(year, real_2015_mean) |>
  left_join(old |> select(cal_year, real_2015_old = mean_staffing_real_2015), by = c("year" = "cal_year")) |>
  mutate(pct_change = round(100 * (real_2015_mean - real_2015_old) / real_2015_old, 1))
print(comp)

cat("\nfiles written:\n -", OUT_CSV, "\n -", OUT_ROB, "\n")
cat("\n✅ 1991 RESOLVED 7 Sep — filled from the Mortimore & Blick (2018) successor edition",
    "cross-check (was wrongly treated as a genuine gap; see SOURCE_NOTE.md).\n")
cat("✅ Repointed into 41e/build_fig_3_2/41f/41g/41i/41j — headline spec is mean_ratio;",
    "min/max ratio and old-85% specs kept as columns for robustness.\n")
